// Auth endpoints - session-based login

// POST /api/auth/login — Email/password login
app.post('/api/auth/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const loginType = typeof req.body?.type === 'string' ? req.body.type.toLowerCase() : 'general';
    const loginAs = typeof req.body?.loginAs === 'string' ? req.body.loginAs.toLowerCase().trim() : '';
    const requestedRole = typeof req.body?.role === 'string' ? req.body.role.toLowerCase().trim() : '';
    const isRoleRoomLogin = loginAs === 'production_team' || loginAs === 'content_producer';
    const isProductionEnv = process.env.NODE_ENV === 'production';
    const roleRoomGuestPassword = process.env.ROLE_ROOM_GUEST_PASSWORD || process.env.PROTOTYPE_GUEST_PASSWORD || 'guest-access';
    if (!email) return res.status(400).json({ error: 'E-post er påkrevd' });
    const normalizedEmail = email.toLowerCase().trim();
    const prototypeGuestEmails = new Set([
      'academy-guest@creatorhubn.com',
    ]);

    // Look up user by email
    let result = await pool.query(
      'SELECT id, email, username, first_name, last_name, password, role FROM users WHERE email = $1',
      [normalizedEmail]
    );

    if ((!result.rowCount || result.rowCount === 0) && isRoleRoomLogin && !isProductionEnv) {
      const bcrypt = await import('bcrypt');
      const safePassword = typeof password === 'string' && password.trim().length > 0
        ? password
        : roleRoomGuestPassword;
      const hashedPassword = await bcrypt.default.hash(safePassword, 10);
      const inferredFirstName = normalizedEmail.split('@')[0]?.slice(0, 64) || 'Role Room';

      result = await pool.query(
        `INSERT INTO users (email, first_name, role, password, is_active, created_at, updated_at)
         VALUES ($1, $2, 'user', $3, true, NOW(), NOW())
         ON CONFLICT (email) DO UPDATE
         SET password = COALESCE(NULLIF(users.password, ''), EXCLUDED.password),
             first_name = COALESCE(NULLIF(users.first_name, ''), EXCLUDED.first_name),
             is_active = true,
             updated_at = NOW()
         RETURNING id, email, username, first_name, last_name, password, role`,
        [normalizedEmail, inferredFirstName, hashedPassword],
      );
    }

    if (!result.rowCount || result.rowCount === 0) {
      return res.status(401).json({ error: 'Ugyldig e-post eller passord' });
    }

    const dbUser = result.rows[0];
    const storedPassword = typeof dbUser.password === 'string' ? dbUser.password : '';

    if (storedPassword) {
      const bcrypt = await import('bcrypt');
      const isPasswordHashed = /^\$2[ayb]\$/.test(storedPassword);
      const passwordValid = isPasswordHashed
        ? await bcrypt.default.compare(password || '', storedPassword)
        : password === storedPassword;

      if (!passwordValid) {
        return res.status(401).json({ error: 'Ugyldig e-post eller passord' });
      }
    } else {
      const prototypeGuestPassword = process.env.PROTOTYPE_GUEST_PASSWORD || 'guest-access';
      const canUsePrototypeFallback = loginType === 'prototype' && prototypeGuestEmails.has(dbUser.email);
      const canUseRoleRoomFallback = isRoleRoomLogin && !isProductionEnv;
      const roleRoomPasswordValid = canUseRoleRoomFallback && password === roleRoomGuestPassword;
      if ((!canUsePrototypeFallback || password !== prototypeGuestPassword) && !roleRoomPasswordValid) {
        return res.status(401).json({ error: 'Ugyldig e-post eller passord' });
      }
      if (roleRoomPasswordValid) {
        const bcrypt = await import('bcrypt');
        const hashedPassword = await bcrypt.default.hash(roleRoomGuestPassword, 10);
        await pool.query(
          `UPDATE users
           SET password = $2, updated_at = NOW()
           WHERE id = $1 AND (password IS NULL OR password = '')`,
          [dbUser.id, hashedPassword],
        ).catch(() => undefined);
      }
    }

    // Determine role
    let role = 'user';
    const dbRole = String(dbUser.role || '').toLowerCase();
    const fullAccessGuestEmails = new Set([
      'daniel@creatorhubn.com',
      'academy-guest@creatorhubn.com',
    ]);
    if (dbRole === 'admin' || dbRole === 'super_admin' || fullAccessGuestEmails.has(dbUser.email)) {
      role = 'admin';
    }
    if (loginType === 'prototype') {
      if (dbRole === 'prototype_tester' || prototypeGuestEmails.has(dbUser.email)) {
        role = 'prototype_tester';
      } else {
        return res.status(403).json({ error: 'Prototype tester-tilgang krever godkjenning' });
      }
    }
    
    // Check couple_profiles
    const coupleCheck = await pool.query(
      'SELECT id, display_name FROM couple_profiles WHERE email = $1 LIMIT 1',
      [dbUser.email]
    ).catch(() => ({ rows: [], rowCount: 0 }));

    if (loginType !== 'prototype' && coupleCheck.rows.length > 0) role = 'couple';

    // Check vendors table
    const vendorCheck = await pool.query(
      'SELECT id, business_name FROM vendors WHERE email = $1 LIMIT 1',
      [dbUser.email]
    ).catch(() => ({ rows: [], rowCount: 0 }));

    if (loginType !== 'prototype' && vendorCheck.rows.length > 0) role = 'vendor';

    // Create session token
    const sessionToken = crypto.randomUUID();
    const name = [dbUser.first_name, dbUser.last_name].filter(Boolean).join(' ') || dbUser.username;

    const sessionData = {
      userId: dbUser.id,
      email: dbUser.email,
      name,
      role,
      loginAt: new Date().toISOString()
    };
    activeSessions.set(sessionToken, sessionData);

    console.log(`[Auth] Login: ${dbUser.email} as ${role} (session: ${sessionToken.substring(0, 8)}...)`);

    res.json({
      success: true,
      token: sessionToken,
      user: {
        id: dbUser.id,
        email: dbUser.email,
        name,
        role,
        ...(isRoleRoomLogin ? {
          requestedRole: requestedRole || null,
          loginAs,
        } : {}),
        ...(role === 'vendor' && vendorCheck.rows.length > 0 ? {
          vendorId: vendorCheck.rows[0].id,
          businessName: vendorCheck.rows[0].business_name
        } : {}),
        ...(role === 'couple' && coupleCheck.rows.length > 0 ? {
          coupleProfileId: coupleCheck.rows[0].id,
          displayName: coupleCheck.rows[0].display_name
        } : {})
      }
    });
  } catch (error) {
    console.error('Login error:', error);
    res.status(500).json({ error: 'Innlogging feilet' });
  }
});

// POST /api/couples/login — Couple login (compatible with deployed Evendi API)
app.post('/api/couples/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    if (!email) return res.status(400).json({ error: 'E-post er påkrevd' });

    console.log(`[CoupleLogin] Login attempt for email: ${email}`);

    // Look up couple profile
    const coupleResult = await pool.query(
      'SELECT id, email, display_name, password, partner_email, wedding_date FROM couple_profiles WHERE email = $1 LIMIT 1',
      [email.toLowerCase().trim()]
    );

    if (!coupleResult.rowCount || coupleResult.rowCount === 0) {
      console.log(`[CoupleLogin] Lookup result: Not found`);
      return res.status(401).json({ error: 'Ugyldig e-post eller passord' });
    }

    const couple = coupleResult.rows[0];
    console.log(`[CoupleLogin] Lookup result: Found`);

    // Verify password with bcrypt if hashed, or plain comparison
    if (couple.password) {
      const bcrypt = await import('bcrypt');
      const isPasswordHashed = /^\$2[ayb]\$/.test(couple.password);
      let passwordValid = false;

      if (isPasswordHashed) {
        passwordValid = await bcrypt.default.compare(password || '', couple.password);
      } else {
        passwordValid = password === couple.password;
      }

      if (!passwordValid) {
        return res.status(401).json({ error: 'Ugyldig e-post eller passord' });
      }
    }

    // Also look up in users table 
    const userResult = await pool.query(
      'SELECT id FROM users WHERE email = $1 LIMIT 1',
      [email.toLowerCase().trim()]
    ).catch(() => ({ rows: [] }));

    const userId = userResult.rows[0]?.id || couple.id;

    // Create session
    const sessionToken = crypto.randomUUID();
    const sessionData = {
      userId,
      email: couple.email,
      name: couple.display_name || email,
      role: 'couple' as const,
      loginAt: new Date().toISOString()
    };
    activeSessions.set(sessionToken, sessionData);

    console.log(`[CoupleLogin] Success: ${couple.email} (session: ${sessionToken.substring(0, 8)}...)`);

    res.json({
      success: true,
      token: sessionToken,
      user: {
        id: userId,
        email: couple.email,
        name: couple.display_name || email,
        role: 'couple',
        coupleProfileId: couple.id,
        displayName: couple.display_name,
        partnerEmail: couple.partner_email,
        weddingDate: couple.wedding_date
      }
    });
  } catch (error) {
    console.error('[CoupleLogin] Error:', error);
    res.status(500).json({ error: 'Innlogging feilet' });
  }
});

