app.post('/api/story-arc/v2/benchmark/golden/run', async (req, res) => {
  try {
    const datasetName = readString(req.body?.datasetName) || 'storyarc-v2-golden';
    const rawCases = Array.isArray(req.body?.cases) ? req.body.cases : [];
    const testCases: StoryArcV2GoldenBenchmarkCase[] = rawCases
      .map((entry: unknown, index: number) => {
        if (!isUnknownRecord(entry)) return null;
        const analysisId = readString(entry.analysisId);
        if (!analysisId) return null;
        const variantRaw = normalizeModelLookupValue(readString(entry.variant) || 'balanced');
        const variant: StoryArcV2Variant =
          variantRaw === 'safe' || variantRaw === 'bold' ? (variantRaw as StoryArcV2Variant) : 'balanced';
        return {
          caseId: readString(entry.caseId) || `case-${index + 1}`,
          analysisId,
          targetDuration: Number(
            clampStoryArcV2Number(readNumber(entry.targetDuration) ?? 90, 20, 1800).toFixed(2)
          ),
          variant,
          minOverallScore: Number(
            clampStoryArcV2Number(readNumber(entry.minOverallScore) ?? 0.65, 0, 1).toFixed(3)
          ),
          minBeatCoverage: Number(
            clampStoryArcV2Number(readNumber(entry.minBeatCoverage) ?? 0.95, 0, 1).toFixed(3)
          ),
        };
      })
      .filter((entry: StoryArcV2GoldenBenchmarkCase | null): entry is StoryArcV2GoldenBenchmarkCase =>
        entry !== null
      );

    if (testCases.length === 0) {
      return res.status(400).json({ success: false, error: 'At least one valid benchmark case is required' });
    }

    const run = await runStoryArcV2GoldenBenchmark(datasetName, testCases);
    return res.json({ success: true, run });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to run golden benchmark';
    return res.status(500).json({ success: false, error: message });
  }
});

app.get('/api/story-arc/v2/benchmark/golden/runs', async (req, res) => {
  try {
    const limit = Math.max(1, Math.min(50, Math.round(readNumber(req.query?.limit) ?? 10)));
    let runs = Array.from(storyArcV2GoldenBenchmarkRuns.values()).sort((left, right) =>
      right.startedAt.localeCompare(left.startedAt)
    );

    if (runs.length < limit && (await hasTable('storyarc_golden_benchmark_runs'))) {
      const result = await pool.query(
        `select run_payload from storyarc_golden_benchmark_runs
         order by created_at desc
         limit $1`,
        [limit]
      );
      result.rows.forEach((row) => {
        if (!isUnknownRecord(row.run_payload)) return;
        const run = row.run_payload as unknown as StoryArcV2GoldenBenchmarkRun;
        if (!run.runId) return;
        storyArcV2GoldenBenchmarkRuns.set(run.runId, run);
      });
      runs = Array.from(storyArcV2GoldenBenchmarkRuns.values()).sort((left, right) =>
        right.startedAt.localeCompare(left.startedAt)
      );
    }

    return res.json({
      success: true,
      total: Math.min(limit, runs.length),
      runs: runs.slice(0, limit),
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to list benchmark runs';
    return res.status(500).json({ success: false, error: message });
  }
});

app.get('/api/story-arc/v2/observability/metrics', async (req, res) => {
  try {
    const windowDays = Math.max(1, Math.min(90, Math.round(readNumber(req.query?.windowDays) ?? 14)));
    const limit = Math.max(50, Math.min(5_000, Math.round(readNumber(req.query?.limit) ?? 1_000)));

    const phaseSamples = await loadStoryArcV2PhaseMetricsForWindow(windowDays, limit);
    const phaseSnapshot = summarizeStoryArcV2PhaseMetrics(phaseSamples);
    const qualityScorecards = await loadStoryArcV2QualityScorecardsForWindow(windowDays, limit);
    const qualityTrend = buildStoryArcV2QualityTrend(qualityScorecards);

    return res.json({
      success: true,
      generatedAt: new Date().toISOString(),
      windowDays,
      sampleLimit: limit,
      failRate: phaseSnapshot.totals,
      phaseLatency: phaseSnapshot.phases,
      qualityTrend: qualityTrend.summary,
      qualityPoints: qualityTrend.points.slice(-Math.min(500, limit)),
      source: {
        phaseSamples: phaseSamples.length,
        qualityScorecards: qualityScorecards.length,
      },
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to load Story Arc V2 observability metrics';
    return res.status(500).json({ success: false, error: message });
  }
});

app.post('/api/story-arc/v2/export', async (req, res) => {
  const completePhaseMetric = createStoryArcV2PhaseMetricRecorder('export', {
    operation: 'export',
  });
  try {
    const proposalId = readString(req.body?.proposalId);
    if (!proposalId) {
      completePhaseMetric('failed', { reason: 'missing_proposal_id' });
      return res.status(400).json({ success: false, error: 'Missing proposalId' });
    }
    const proposal = await loadStoryArcV2ProposalFromDb(proposalId);
    if (!proposal) {
      completePhaseMetric('failed', { reason: 'proposal_not_found', proposalId });
      return res.status(404).json({ success: false, error: 'Proposal not found' });
    }
    const formatRaw = normalizeModelLookupValue(readString(req.body?.format) || 'fcpxml');
    const format =
      formatRaw === 'xml' || formatRaw === 'resolve-json'
        ? formatRaw
        : 'fcpxml';
    const includeScriptNotes = readBoolean(req.body?.includeScriptNotes) !== false;
    const selected = proposal.variants[proposal.selectedVariant];
    if (!selected) {
      completePhaseMetric('failed', {
        reason: 'selected_variant_missing',
        proposalId,
        selectedVariant: proposal.selectedVariant,
      });
      return res.status(400).json({ success: false, error: 'Selected variant missing in proposal' });
    }

    const generatedAt = new Date().toISOString();
    if (format === 'resolve-json') {
      completePhaseMetric('completed', {
        proposalId,
        format,
        selectedVariant: proposal.selectedVariant,
        clipCount: selected.timeline.clips.length,
      });
      return res.json({
        success: true,
        proposalId,
        format,
        fileName: `storyarc-${proposalId}.resolve.json`,
        content: {
          proposalId,
          selectedVariant: proposal.selectedVariant,
          timeline: selected.timeline,
          editDecisions: proposal.editDecisions,
          notes: includeScriptNotes
            ? selected.timeline.clips.map((clip) => ({
                clipId: clip.id,
                note: readString(clip.metadata?.rationale) || '',
              }))
            : [],
        },
        generatedAt,
      });
    }

    const content =
      format === 'xml'
        ? JSON.stringify(selected.timeline, null, 2)
        : buildStoryArcV2Fcpxml(proposal);

    completePhaseMetric('completed', {
      proposalId,
      format,
      selectedVariant: proposal.selectedVariant,
      clipCount: selected.timeline.clips.length,
    });
    return res.json({
      success: true,
      proposalId,
      format,
      fileName: `storyarc-${proposalId}.${format === 'fcpxml' ? 'fcpxml' : 'xml'}`,
      content,
      editDecisions: proposal.editDecisions,
      includeScriptNotes,
      generatedAt,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Failed to export timeline';
    completePhaseMetric('failed', { reason: 'exception', error: message });
    return res.status(500).json({ success: false, error: message });
  }
});

