// User Interface Preferences API - DB Persistence
// ============================================

// Get user interface preferences
app.get('/api/user/interface-preferences/:sessionId', async (req, res) => {
  const { sessionId } = req.params;
  const fromCompatMemory = compatInterfacePreferencesStore.get(sessionId);
  if (fromCompatMemory) {
    return res.json({
      success: true,
      preferences: fromCompatMemory,
      source: 'compat-store',
    });
  }

  const fromCompatDb = await compatStoreGet<Record<string, unknown>>(dbCompatInterfacePreferencesKey(sessionId));
  if (fromCompatDb && typeof fromCompatDb === 'object') {
    compatInterfacePreferencesStore.set(sessionId, fromCompatDb);
    return res.json({
      success: true,
      preferences: fromCompatDb,
      source: 'compat-store',
    });
  }
  
  try {
    const prefs = await db.select().from(schema.userPreferences).where(eq(schema.userPreferences.sessionId, sessionId));
    
    if (prefs.length > 0) {
      return res.json({
        success: true,
        preferences: prefs[0],
        source: 'database'
      });
    }
    
    // Return defaults if no preferences found
    res.json({
      success: true,
      preferences: {
        theme: 'light',
        language: 'nb-NO',
        notificationsEnabled: true,
        dashboardLayout: 'cards',
        timezone: 'Europe/Oslo',
        currency: 'NOK'
      },
      source: 'defaults'
    });
  } catch (error) {
    console.error('Error fetching interface preferences:', error);
    res.json({
      success: true,
      preferences: {
        theme: 'light',
        language: 'nb-NO',
        notificationsEnabled: true,
        dashboardLayout: 'cards',
        timezone: 'Europe/Oslo',
        currency: 'NOK'
      },
      source: 'defaults'
    });
  }
});

// Save user interface preferences
app.put('/api/user/interface-preferences/:sessionId', async (req, res) => {
  const { sessionId } = req.params;
  const preferences = req.body;
  const compatNext = {
    ...(compatInterfacePreferencesStore.get(sessionId) || {}),
    ...(preferences || {}),
    updatedAt: new Date().toISOString(),
  };
  compatInterfacePreferencesStore.set(sessionId, compatNext);
  await compatStoreSet(dbCompatInterfacePreferencesKey(sessionId), compatNext);
  
  try {
    // Check if preferences exist
    const existing = await db.select().from(schema.userPreferences).where(eq(schema.userPreferences.sessionId, sessionId));
    
    if (existing.length > 0) {
      // Update existing
      await db.update(schema.userPreferences)
        .set({
          theme: preferences.theme || 'light',
          language: preferences.language || 'nb-NO',
          notificationsEnabled: preferences.notificationsEnabled ?? true,
          dashboardLayout: preferences.dashboardLayout || 'cards',
          timezone: preferences.timezone || 'Europe/Oslo',
          currency: preferences.currency || 'NOK',
          updatedAt: new Date().toISOString()
        })
        .where(eq(schema.userPreferences.sessionId, sessionId));
    } else {
      // Insert new
      await db.insert(schema.userPreferences).values({
        id: crypto.randomUUID(),
        sessionId,
        profession: preferences.profession || 'photographer',
        theme: preferences.theme || 'light',
        language: preferences.language || 'nb-NO',
        notificationsEnabled: preferences.notificationsEnabled ?? true,
        dashboardLayout: preferences.dashboardLayout || 'cards',
        timezone: preferences.timezone || 'Europe/Oslo',
        currency: preferences.currency || 'NOK'
      });
    }
    
    res.json({
      success: true,
      message: 'Preferences saved to database',
      source: 'database'
    });
  } catch (error) {
    console.error('Error saving interface preferences to DB, using compatibility store:', error);
    res.json({
      success: true,
      message: 'Preferences saved to compatibility store',
      source: 'compat-store',
    });
  }
});

