// ============================================
// YR.no (MET Norway) Weather API Integration
// https://api.met.no/weatherapi/locationforecast/2.0/
// ============================================

// Norwegian city coordinates for location lookup
const norwegianCities: Record<string, { lat: number; lon: number }> = {
  oslo: { lat: 59.9139, lon: 10.7522 },
  bergen: { lat: 60.3913, lon: 5.3221 },
  trondheim: { lat: 63.4305, lon: 10.3951 },
  stavanger: { lat: 58.9700, lon: 5.7331 },
  kristiansand: { lat: 58.1599, lon: 8.0182 },
  drammen: { lat: 59.7439, lon: 10.2045 },
  fredrikstad: { lat: 59.2181, lon: 10.9298 },
  tromsø: { lat: 69.6496, lon: 18.9560 },
  sandnes: { lat: 58.8520, lon: 5.7357 },
  sarpsborg: { lat: 59.2839, lon: 11.1097 },
};

// Get current weather from YR.no (MET Norway API)
app.get('/api/price-administration/weather/current/:location', async (req, res) => {
  try {
    const location = req.params.location.toLowerCase();
    const lat = req.query.lat ? parseFloat(req.query.lat as string) : norwegianCities[location]?.lat || 59.9139;
    const lon = req.query.lon ? parseFloat(req.query.lon as string) : norwegianCities[location]?.lon || 10.7522;

    // Call MET Norway Locationforecast API
    const metResponse = await fetch(
      `https://api.met.no/weatherapi/locationforecast/2.0/compact?lat=${lat}&lon=${lon}`,
      {
        headers: {
          'User-Agent': 'CreatorHubNorge/1.0 (https://creatorhub.no; contact@creatorhub.no)',
        },
      }
    );

    if (!metResponse.ok) {
      throw new Error(`MET API error: ${metResponse.status}`);
    }

    const metData = await metResponse.json();
    const current = metData.properties?.timeseries?.[0]?.data;
    
    if (!current) {
      throw new Error('No weather data available');
    }

    const instant = current.instant?.details || {};
    const next1h = current.next_1_hours?.details || {};
    const symbolCode = current.next_1_hours?.summary?.symbol_code || 'cloudy';

    res.json({
      success: true,
      location: location.charAt(0).toUpperCase() + location.slice(1),
      temperature: Math.round(instant.air_temperature || 0),
      humidity: Math.round(instant.relative_humidity || 0),
      pressure: Math.round(instant.air_pressure_at_sea_level || 1013),
      windSpeed: Math.round(instant.wind_speed || 0),
      windDirection: Math.round(instant.wind_from_direction || 0),
      cloudCover: Math.round(instant.cloud_area_fraction || 0),
      visibility: 20, // MET API doesn't provide visibility directly
      uvIndex: Math.round(instant.ultraviolet_index_clear_sky || 0),
      precipitation: next1h.precipitation_amount || 0,
      symbolCode,
      timestamp: new Date().toISOString(),
      source: 'yr_api',
      coordinates: { lat, lon },
    });
  } catch (error) {
    console.error('Weather API error:', error);
    // Return fallback data
    res.json({
      success: true,
      location: req.params.location,
      temperature: 8,
      humidity: 65,
      pressure: 1013,
      windSpeed: 4,
      windDirection: 225,
      cloudCover: 45,
      visibility: 15,
      uvIndex: 2,
      timestamp: new Date().toISOString(),
      source: 'fallback',
    });
  }
});

// Get weather forecast from YR.no (MET Norway API)
app.get('/api/price-administration/weather/forecast/:location', async (req, res) => {
  try {
    const location = req.params.location.toLowerCase();
    const lat = req.query.lat ? parseFloat(req.query.lat as string) : norwegianCities[location]?.lat || 59.9139;
    const lon = req.query.lon ? parseFloat(req.query.lon as string) : norwegianCities[location]?.lon || 10.7522;
    const days = parseInt(req.query.days as string) || 5;

    // Call MET Norway Locationforecast API
    const metResponse = await fetch(
      `https://api.met.no/weatherapi/locationforecast/2.0/compact?lat=${lat}&lon=${lon}`,
      {
        headers: {
          'User-Agent': 'CreatorHubNorge/1.0 (https://creatorhub.no; contact@creatorhub.no)',
        },
      }
    );

    if (!metResponse.ok) {
      throw new Error(`MET API error: ${metResponse.status}`);
    }

    const metData = await metResponse.json();
    const timeseries = metData.properties?.timeseries || [];

    // Group by day and get daily forecasts
    const dailyForecasts: Record<string, any> = {};
    
    for (const entry of timeseries) {
      const date = entry.time.split('T')[0];
      const hour = parseInt(entry.time.split('T')[1].split(':')[0]);
      
      // Use noon (12:00) data for daily forecast, or first available
      if (!dailyForecasts[date] || hour === 12) {
        const instant = entry.data?.instant?.details || {};
        const next6h = entry.data?.next_6_hours?.details || {};
        const symbolCode = entry.data?.next_6_hours?.summary?.symbol_code || 
                          entry.data?.next_1_hours?.summary?.symbol_code || 'cloudy';
        
        dailyForecasts[date] = {
          date,
          temperature: Math.round(instant.air_temperature || 0),
          humidity: Math.round(instant.relative_humidity || 0),
          windSpeed: Math.round(instant.wind_speed || 0),
          precipitation: next6h.precipitation_amount || 0,
          symbol: symbolCode,
        };
      }
    }

    // Convert to array and limit to requested days
    const forecast = Object.values(dailyForecasts).slice(0, days);

    res.json({
      success: true,
      location: location.charAt(0).toUpperCase() + location.slice(1),
      forecast,
      days,
      source: 'yr_api',
      coordinates: { lat, lon },
    });
  } catch (error) {
    console.error('Forecast API error:', error);
    // Return fallback forecast
    const forecast = [];
    const today = new Date();
    const stableTemps = [8, 10, 7, 12, 9, 6, 11];
    const stableSymbols = ['cloudy', 'clearsky_day', 'cloudy', 'rain', 'clearsky_day', 'cloudy', 'fair_day'];
    
    for (let i = 0; i < (parseInt(req.query.days as string) || 5); i++) {
      const date = new Date(today);
      date.setDate(today.getDate() + i);
      forecast.push({
        date: date.toISOString().split('T')[0],
        temperature: stableTemps[i % stableTemps.length],
        humidity: 60 + (i * 3) % 20,
        windSpeed: 3 + (i % 5),
        precipitation: i % 3 === 0 ? 2 : 0,
        symbol: stableSymbols[i % stableSymbols.length],
      });
    }
    
    res.json({
      success: true,
      location: req.params.location,
      forecast,
      days: parseInt(req.query.days as string) || 5,
      source: 'fallback',
    });
  }
});

// Get derived weather alerts from MET/yr forecast (next N hours)
app.get('/api/price-administration/weather/alerts/:location', async (req, res) => {
  try {
    const location = req.params.location.toLowerCase();
    const lat = req.query.lat ? parseFloat(req.query.lat as string) : norwegianCities[location]?.lat || 59.9139;
    const lon = req.query.lon ? parseFloat(req.query.lon as string) : norwegianCities[location]?.lon || 10.7522;
    const horizonHours = Math.max(6, Math.min(72, parseInt(req.query.hours as string, 10) || 24));

    const metResponse = await fetch(
      `https://api.met.no/weatherapi/locationforecast/2.0/compact?lat=${lat}&lon=${lon}`,
      {
        headers: {
          'User-Agent': 'CreatorHubNorge/1.0 (https://creatorhub.no; contact@creatorhub.no)',
        },
      }
    );

    if (!metResponse.ok) {
      throw new Error(`MET API error: ${metResponse.status}`);
    }

    const metData = await metResponse.json();
    const timeseries = Array.isArray(metData?.properties?.timeseries) ? metData.properties.timeseries : [];
    const nowMs = Date.now();
    const endMs = nowMs + horizonHours * 60 * 60 * 1000;

    const upcoming = timeseries.filter((entry: any) => {
      const ts = Date.parse(entry?.time);
      return Number.isFinite(ts) && ts >= nowMs && ts <= endMs;
    });

    if (upcoming.length === 0) {
      return res.json({
        success: true,
        location: location.charAt(0).toUpperCase() + location.slice(1),
        alerts: [],
        source: 'yr_api',
        horizonHours,
        coordinates: { lat, lon },
      });
    }

    const getWind = (entry: any): number => Number(entry?.data?.instant?.details?.wind_speed || 0);
    const getPrecip = (entry: any): number =>
      Number(
        entry?.data?.next_1_hours?.details?.precipitation_amount
        ?? entry?.data?.next_6_hours?.details?.precipitation_amount
        ?? 0
      );
    const getSymbol = (entry: any): string =>
      String(
        entry?.data?.next_1_hours?.summary?.symbol_code
        ?? entry?.data?.next_6_hours?.summary?.symbol_code
        ?? ''
      );
    const toClock = (iso?: string): string => {
      if (!iso) return '';
      const date = new Date(iso);
      if (Number.isNaN(date.getTime())) return '';
      return date.toLocaleTimeString('nb-NO', { hour: '2-digit', minute: '2-digit' });
    };

    let maxWind = 0;
    let maxWindTime = '';
    let maxPrecip = 0;
    let maxPrecipTime = '';
    let hasThunder = false;
    let thunderTime = '';
    let hasSnowOrSleet = false;
    let snowOrSleetTime = '';

    for (const entry of upcoming) {
      const wind = getWind(entry);
      if (wind > maxWind) {
        maxWind = wind;
        maxWindTime = entry?.time || '';
      }

      const precipitation = getPrecip(entry);
      if (precipitation > maxPrecip) {
        maxPrecip = precipitation;
        maxPrecipTime = entry?.time || '';
      }

      const symbol = getSymbol(entry);
      if (!hasThunder && /thunder|lightning/i.test(symbol)) {
        hasThunder = true;
        thunderTime = entry?.time || '';
      }
      if (!hasSnowOrSleet && /snow|sleet|freezingrain|freezing/i.test(symbol)) {
        hasSnowOrSleet = true;
        snowOrSleetTime = entry?.time || '';
      }
    }

    const alerts: Array<{
      level: 'info' | 'warning' | 'critical';
      type: string;
      title: string;
      message: string;
      startsAt?: string;
    }> = [];

    if (maxWind >= 20) {
      alerts.push({
        level: 'critical',
        type: 'storm',
        title: 'Storm på vei',
        message: `Kraftig vind opp mot ${Math.round(maxWind)} m/s forventes rundt kl. ${toClock(maxWindTime)}.`,
        startsAt: maxWindTime,
      });
    } else if (maxWind >= 14) {
      alerts.push({
        level: 'warning',
        type: 'wind',
        title: 'Kraftig vind i vente',
        message: `Vind opp mot ${Math.round(maxWind)} m/s forventes rundt kl. ${toClock(maxWindTime)}.`,
        startsAt: maxWindTime,
      });
    } else if (maxWind >= 10) {
      alerts.push({
        level: 'info',
        type: 'wind',
        title: 'Frisk vind varslet',
        message: `Vind kan nå ${Math.round(maxWind)} m/s de neste ${horizonHours} timene.`,
        startsAt: maxWindTime,
      });
    }

    if (maxPrecip >= 8) {
      alerts.push({
        level: 'warning',
        type: 'rain',
        title: 'Kraftig nedbør i vente',
        message: `Nedbør opp mot ${maxPrecip.toFixed(1)} mm forventes rundt kl. ${toClock(maxPrecipTime)}.`,
        startsAt: maxPrecipTime,
      });
    } else if (maxPrecip >= 3) {
      alerts.push({
        level: 'info',
        type: 'rain',
        title: 'Regnbyger varslet',
        message: `Nedbør opp mot ${maxPrecip.toFixed(1)} mm forventes i perioden.`,
        startsAt: maxPrecipTime,
      });
    }

    if (hasThunder) {
      alerts.push({
        level: 'warning',
        type: 'thunder',
        title: 'Fare for torden',
        message: `Tordenvær er varslet rundt kl. ${toClock(thunderTime)}. Vurder sikkerhet for crew og utstyr.`,
        startsAt: thunderTime,
      });
    }

    if (hasSnowOrSleet) {
      alerts.push({
        level: 'info',
        type: 'surface',
        title: 'Glatt føre kan oppstå',
        message: `Snø/sludd/frysende nedbør er varslet rundt kl. ${toClock(snowOrSleetTime)}.`,
        startsAt: snowOrSleetTime,
      });
    }

    res.json({
      success: true,
      location: location.charAt(0).toUpperCase() + location.slice(1),
      alerts,
      source: 'yr_api',
      horizonHours,
      coordinates: { lat, lon },
      summary: {
        maxWind: Math.round(maxWind),
        maxPrecipitation: Number(maxPrecip.toFixed(1)),
      },
    });
  } catch (error) {
    console.error('Weather alerts API error:', error);
    res.json({
      success: true,
      location: req.params.location,
      alerts: [],
      source: 'fallback',
    });
  }
});

// ============================================
// SPLIT SHEETS API - PostgreSQL-backed
// ============================================

function getSplitSheetUserId(req: any): string {
  const authHeader = req.headers?.authorization;
  const bearerToken =
    typeof authHeader === 'string' && authHeader.startsWith('Bearer ')
      ? authHeader.slice(7).trim()
      : '';
  const sessionUserId =
    bearerToken && activeSessions.has(bearerToken)
      ? activeSessions.get(bearerToken)?.userId
      : '';

  const rawUserId =
    req.session?.user?.id ||
    req.user?.id ||
    sessionUserId ||
    req.headers['x-user-id'] ||
    req.body?.userId ||
    req.query?.userId ||
    req.headers['x-userid'] ||
    req.headers['x-user'];

  if (typeof rawUserId === 'string' && rawUserId.trim().length > 0) {
    return rawUserId.trim();
  }
  return '';
}

function requireEaseVerseUserId(req: any, res: any): string | null {
  const userId = getSplitSheetUserId(req);
  if (userId) {
    return userId;
  }

  res.status(401).json({
    success: false,
    error: 'Missing user identity. Provide x-user-id header or authenticate the request.'
  });
  return null;
}

const EASEVERSE_API_URL = (process.env.EASEVERSE_API_URL || '').trim().replace(/\/+$/, '');
const EASEVERSE_API_KEY = (process.env.EASEVERSE_API_KEY || '').trim();
let easeVerseSchemaReadyPromise: Promise<void> | null = null;
const SONGFLOW_ALIAS_SUNSET = 'Wed, 31 Dec 2026 23:59:59 GMT';

async function ensureEaseVerseSchema(): Promise<void> {
  if (!easeVerseSchemaReadyPromise) {
    easeVerseSchemaReadyPromise = (async () => {
      await pool.query(`
        CREATE TABLE IF NOT EXISTS easeverse_projects (
          id UUID PRIMARY KEY,
          user_id VARCHAR(255) NOT NULL,
          name VARCHAR(255) NOT NULL,
          artist VARCHAR(255) NOT NULL DEFAULT '',
          status VARCHAR(50) NOT NULL DEFAULT 'active',
          deadline TIMESTAMPTZ NULL,
          google_workspace_sync BOOLEAN NOT NULL DEFAULT true,
          last_sync TIMESTAMPTZ NULL,
          created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        );
      `);

      await pool.query(`
        CREATE INDEX IF NOT EXISTS idx_easeverse_projects_user_id
        ON easeverse_projects(user_id);
      `);

      await pool.query(`
        CREATE TABLE IF NOT EXISTS easeverse_tracks (
          id UUID PRIMARY KEY,
          user_id VARCHAR(255) NOT NULL,
          project_id UUID NULL REFERENCES easeverse_projects(id) ON DELETE SET NULL,
          title VARCHAR(255) NOT NULL,
          artist VARCHAR(255) NOT NULL,
          duration_seconds INTEGER NOT NULL DEFAULT 0,
          genre VARCHAR(120) NOT NULL DEFAULT 'pop',
          status VARCHAR(50) NOT NULL DEFAULT 'recording'
            CHECK (status IN ('recording', 'mixing', 'mastering', 'completed')),
          bpm INTEGER NOT NULL DEFAULT 120,
          musical_key VARCHAR(16) NOT NULL DEFAULT 'C',
          collaborators JSONB NOT NULL DEFAULT '[]'::jsonb,
          notes TEXT NOT NULL DEFAULT '',
          lyrics TEXT NOT NULL DEFAULT '',
          stem_files INTEGER NOT NULL DEFAULT 0,
          google_drive_backup BOOLEAN NOT NULL DEFAULT false,
          last_backup TIMESTAMPTZ NULL,
          last_lyric_sync TIMESTAMPTZ NULL,
          created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        );
      `);

      await pool.query(`
        CREATE INDEX IF NOT EXISTS idx_easeverse_tracks_user_id
        ON easeverse_tracks(user_id);
      `);

      await pool.query(`
        CREATE INDEX IF NOT EXISTS idx_easeverse_tracks_project_id
        ON easeverse_tracks(project_id);
      `);

      await pool.query(`
        CREATE TABLE IF NOT EXISTS split_sheet_songflow_links (
          id UUID PRIMARY KEY,
          split_sheet_id VARCHAR(255) NOT NULL,
          songflow_project_id VARCHAR(255),
          songflow_track_id VARCHAR(255),
          link_type VARCHAR(20) NOT NULL DEFAULT 'track',
          auto_created BOOLEAN NOT NULL DEFAULT false,
          linked_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          linked_by VARCHAR(255),
          metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
          created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
        );
      `);

      await pool.query(`
        CREATE INDEX IF NOT EXISTS idx_split_sheet_songflow_links_split_sheet_id
        ON split_sheet_songflow_links(split_sheet_id);
      `);

      await pool.query(`
        CREATE INDEX IF NOT EXISTS idx_split_sheet_songflow_links_track_id
        ON split_sheet_songflow_links(songflow_track_id);
      `);
    })();
  }

  return easeVerseSchemaReadyPromise;
}

function parseCollaborators(collaborators: unknown): string[] {
  if (Array.isArray(collaborators)) {
    return collaborators
      .filter((entry): entry is string => typeof entry === 'string')
      .map((entry) => entry.trim())
      .filter(Boolean);
  }

  if (typeof collaborators === 'string' && collaborators.trim().length > 0) {
    try {
      const parsed = JSON.parse(collaborators);
      if (Array.isArray(parsed)) {
        return parsed
          .filter((entry): entry is string => typeof entry === 'string')
          .map((entry) => entry.trim())
          .filter(Boolean);
      }
    } catch {
      return collaborators
        .split(',')
        .map((entry) => entry.trim())
        .filter(Boolean);
    }
  }

  return [];
}

function mapEaseVerseTrackRow(row: any) {
  return {
    id: row.id,
    title: row.title,
    artist: row.artist,
    duration: Number(row.duration_seconds || 0),
    genre: row.genre || 'pop',
    status: row.status || 'recording',
    bpm: Number(row.bpm || 120),
    key: row.musical_key || 'C',
    googleDriveBackup: Boolean(row.google_drive_backup),
    lastBackup: row.last_backup || null,
    collaborators: parseCollaborators(row.collaborators),
    notes: row.notes || '',
    lyrics: row.lyrics || '',
    stemFiles: Number(row.stem_files || 0),
    projectId: row.project_id || null,
    projectName: row.project_name || null,
    lastLyricSync: row.last_lyric_sync || null,
    createdAt: row.created_at || null,
    updatedAt: row.updated_at || null
  };
}

function mapEaseVerseSplitSheetLinkRow(row: any) {
  const easeverseProjectId = row.songflow_project_id || null;
  const easeverseTrackId = row.songflow_track_id || null;
  return {
    id: row.id,
    splitSheetId: row.split_sheet_id,
    easeverseProjectId,
    easeverseTrackId,
    linkType: row.link_type,
    autoCreated: Boolean(row.auto_created),
    linkedAt: row.linked_at || null,
    linkedBy: row.linked_by || null,
    metadata: row.metadata || {},

    // Deprecated compatibility fields (SongFlow + snake_case)
    easeverse_project_id: easeverseProjectId,
    easeverse_track_id: easeverseTrackId,
    songflow_project_id: easeverseProjectId,
    songflow_track_id: easeverseTrackId,
    split_sheet_id: row.split_sheet_id,
    link_type: row.link_type,
    auto_created: Boolean(row.auto_created),
    linked_at: row.linked_at || null,
    linked_by: row.linked_by || null
  };
}

function resolveEaseVerseLinkIds(input: any): {
  easeverseTrackId: string | null;
  easeverseProjectId: string | null;
} {
  const trackCandidate =
    input?.easeverseTrackId ??
    input?.easeverse_track_id ??
    input?.songflowTrackId ??
    input?.songflow_track_id ??
    null;
  const projectCandidate =
    input?.easeverseProjectId ??
    input?.easeverse_project_id ??
    input?.songflowProjectId ??
    input?.songflow_project_id ??
    null;

  const easeverseTrackId =
    typeof trackCandidate === 'string' && trackCandidate.trim().length > 0
      ? trackCandidate.trim()
      : null;
  const easeverseProjectId =
    typeof projectCandidate === 'string' && projectCandidate.trim().length > 0
      ? projectCandidate.trim()
      : null;

  return { easeverseTrackId, easeverseProjectId };
}

function markSongFlowAliasDeprecated(res: any, successorPath: string) {
  res.setHeader('Deprecation', 'true');
  res.setHeader('Sunset', SONGFLOW_ALIAS_SUNSET);
  res.setHeader('X-API-Deprecated', 'true');
  res.setHeader('X-API-Successor', successorPath);
  res.setHeader('Link', `<${successorPath}>; rel="successor-version"`);
  res.setHeader(
    'Warning',
    `299 - "SongFlow alias route is deprecated; use ${successorPath}"`
  );
}

async function syncLyricsToEaseVerse(payload: {
  externalTrackId: string;
  projectId?: string | null;
  title: string;
  artist: string;
  lyrics: string;
  collaborators: string[];
}) {
  if (!EASEVERSE_API_URL) {
    return {
      success: false,
      skipped: true,
      reason: 'EASEVERSE_API_URL is not configured'
    };
  }

  try {
    const headers: Record<string, string> = {
      'Content-Type': 'application/json'
    };
    if (EASEVERSE_API_KEY) {
      headers['x-api-key'] = EASEVERSE_API_KEY;
    }

    const response = await fetch(`${EASEVERSE_API_URL}/api/v1/collab/lyrics`, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        externalTrackId: payload.externalTrackId,
        projectId: payload.projectId || undefined,
        title: payload.title,
        artist: payload.artist,
        lyrics: payload.lyrics,
        collaborators: payload.collaborators,
        source: 'creatorhub',
        updatedAt: new Date().toISOString()
      })
    });

    const rawResponse = await response.text();
    let parsedResponse: any = null;
    try {
      parsedResponse = rawResponse ? JSON.parse(rawResponse) : null;
    } catch {
      parsedResponse = null;
    }

    if (!response.ok) {
      return {
        success: false,
        status: response.status,
        error:
          parsedResponse?.error ||
          rawResponse ||
          `EaseVerse lyric sync failed (${response.status})`
      };
    }

    return {
      success: true,
      status: response.status,
      data: parsedResponse
    };
  } catch (error: any) {
    return {
      success: false,
      error: error?.message || 'Could not reach EaseVerse API'
    };
  }
}

const listEaseVerseProjectsHandler = async (req: any, res: any) => {
  try {
    await ensureEaseVerseSchema();
    const userId = requireEaseVerseUserId(req, res);
    if (!userId) return;

    const projectsResult = await pool.query(
      `
        SELECT
          p.id,
          p.name,
          p.artist,
          p.status,
          p.deadline,
          p.google_workspace_sync,
          p.last_sync,
          p.created_at,
          p.updated_at
        FROM easeverse_projects p
        WHERE p.user_id = $1
        ORDER BY p.updated_at DESC
      `,
      [userId]
    );

    const tracksResult = await pool.query(
      `
        SELECT
          t.*,
          p.name as project_name
        FROM easeverse_tracks t
        LEFT JOIN easeverse_projects p ON p.id = t.project_id
        WHERE t.user_id = $1
        ORDER BY t.created_at DESC
      `,
      [userId]
    );

    const tracksByProject = new Map<string, any[]>();
    for (const track of tracksResult.rows) {
      if (!track.project_id) continue;
      if (!tracksByProject.has(track.project_id)) {
        tracksByProject.set(track.project_id, []);
      }
      tracksByProject.get(track.project_id)!.push(mapEaseVerseTrackRow(track));
    }

    const projects = projectsResult.rows.map((project) => ({
      id: project.id,
      name: project.name,
      artist: project.artist,
      status: project.status,
      deadline: project.deadline,
      googleWorkspaceSync: Boolean(project.google_workspace_sync),
      lastSync: project.last_sync,
      tracks: tracksByProject.get(project.id) || []
    }));

    res.json(projects);
  } catch (error) {
    console.error('Error fetching EaseVerse projects:', error);
    res.status(500).json({ success: false, error: 'Failed to fetch EaseVerse projects' });
  }
};

